// Package release publishes and reads immutable release manifests.
//
// A release names a set of built bits: a component version, the source commit
// it was built from, the image digests CI published for that commit, and notes
// describing what changed. It is metadata only — creating a release changes no
// environment. Deployments pin digests; releases record which digests belong
// together under a version.
//
// The manifest is stored as a tag-addressed OCI artifact alongside the images
// it describes, so nothing but the OCI Distribution Spec is needed to read it.
package release

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

// SchemaVersion is the manifest format version. Bump only for incompatible
// changes; additive fields do not require a bump.
const SchemaVersion = 1

// Manifest is the immutable record of one release.
//
// Field names are stable and additive-only. These documents outlive the CLI
// that wrote them — they sit in customer registries, and the format is
// immutable by design — so a rename is a breaking change to every reader.
type Manifest struct {
	SchemaVersion int         `json:"schemaVersion"`
	Component     string      `json:"component"`
	Version       string      `json:"version"`
	CreatedAt     time.Time   `json:"createdAt"`
	CreatedBy     string      `json:"createdBy"`
	Source        Source      `json:"source"`
	Images        []Image     `json:"images"`
	Notes         string      `json:"notes"`
	Changes       []Change    `json:"changes"`
	ChangeBasis   ChangeBasis `json:"changeBasis"`
}

// Source identifies the commit the release was built from.
type Source struct {
	Commit string `json:"commit"`
	Ref    string `json:"ref"`
	Repo   string `json:"repo,omitempty"`
}

// Image is one image repository pinned to the digest CI published.
//
// There is deliberately no build timestamp: nothing available when a release
// is created knows when the image was built, and a field that is sometimes a
// guess is worse than no field.
type Image struct {
	Name   string `json:"name"`
	Digest string `json:"digest"`
}

// Change is one commit included in the release.
type Change struct {
	Commit  string `json:"commit"`
	Subject string `json:"subject"`
}

// Basis kinds. A reader that meets an unknown kind should treat Changes as
// present-but-unexplained rather than empty.
const (
	// BasisInitial means nothing had been released, so there was no prior
	// state to compare against.
	BasisInitial = "initial"

	// BasisRelease means Changes was computed against an earlier release.
	BasisRelease = "release"

	// BasisExplicit means the operator named the starting point.
	BasisExplicit = "explicit"
)

// ChangeBasis records what Changes was computed against.
//
// Without it an empty Changes is ambiguous: "nothing changed since the last
// release" and "there was no basis for comparison" are very different claims
// and read identically as []. Every manifest states which one it means.
type ChangeBasis struct {
	Kind string `json:"kind"`

	// Version and Commit identify the predecessor when Kind is BasisRelease.
	Version string `json:"version,omitempty"`
	Commit  string `json:"commit,omitempty"`

	// Ref is what the operator passed to --since when Kind is BasisExplicit.
	Ref string `json:"ref,omitempty"`
}

// Describe renders the basis for a person reading the release.
func (b ChangeBasis) Describe() string {
	switch b.Kind {
	case BasisInitial:
		return "initial release (no previous release to compare against)"
	case BasisRelease:
		return fmt.Sprintf("changes since %s (%s)", b.Version, shortSHA(b.Commit))
	case BasisExplicit:
		return fmt.Sprintf("changes since %s (given with --since)", b.Ref)
	default:
		return b.Kind
	}
}

// ErrInvalidManifest is the base for every validation failure, so callers can
// tell a malformed release from a transport error.
var ErrInvalidManifest = errors.New("invalid release manifest")

// Validate checks a manifest read back from a registry. It is deliberately
// strict about the fields that make a release meaningful and silent about the
// rest: a release with no notes is fine, a release with no digest is not.
func (m *Manifest) Validate() error {
	if m.SchemaVersion != SchemaVersion {
		return fmt.Errorf("%w: schemaVersion %d is not supported (this CLI writes and reads %d)", ErrInvalidManifest, m.SchemaVersion, SchemaVersion)
	}
	if m.Component == "" {
		return fmt.Errorf("%w: component is empty", ErrInvalidManifest)
	}
	if m.Version == "" {
		return fmt.Errorf("%w: version is empty", ErrInvalidManifest)
	}
	if m.Source.Commit == "" {
		return fmt.Errorf("%w: source.commit is empty", ErrInvalidManifest)
	}
	if len(m.Images) == 0 {
		return fmt.Errorf("%w: no images", ErrInvalidManifest)
	}
	for i, img := range m.Images {
		if img.Name == "" {
			return fmt.Errorf("%w: images[%d].name is empty", ErrInvalidManifest, i)
		}
		if !strings.HasPrefix(img.Digest, "sha256:") {
			return fmt.Errorf("%w: images[%d].digest %q is not a sha256 digest", ErrInvalidManifest, i, img.Digest)
		}
	}
	switch m.ChangeBasis.Kind {
	case BasisInitial, BasisExplicit:
	case BasisRelease:
		if m.ChangeBasis.Commit == "" {
			return fmt.Errorf("%w: changeBasis.kind is %q but commit is empty", ErrInvalidManifest, BasisRelease)
		}
	case "":
		return fmt.Errorf("%w: changeBasis.kind is empty, so changes cannot be interpreted", ErrInvalidManifest)
	default:
		return fmt.Errorf("%w: changeBasis.kind %q is unknown", ErrInvalidManifest, m.ChangeBasis.Kind)
	}
	return nil
}

// SameRelease reports whether two manifests describe the same release.
//
// CreatedAt and CreatedBy are excluded: re-running release create for a
// version that already exists must recognise its own earlier work, and those
// two fields differ on every run by construction. Everything else is what the
// release actually claims, and any difference there means the version is being
// reused for something else.
func (m *Manifest) SameRelease(other *Manifest) bool {
	if m == nil || other == nil {
		return false
	}
	if m.SchemaVersion != other.SchemaVersion ||
		m.Component != other.Component ||
		m.Version != other.Version ||
		m.Source != other.Source ||
		m.Notes != other.Notes ||
		m.ChangeBasis != other.ChangeBasis {
		return false
	}
	if len(m.Images) != len(other.Images) {
		return false
	}
	for i := range m.Images {
		if m.Images[i] != other.Images[i] {
			return false
		}
	}
	if len(m.Changes) != len(other.Changes) {
		return false
	}
	for i := range m.Changes {
		if m.Changes[i] != other.Changes[i] {
			return false
		}
	}
	return true
}

func shortSHA(sha string) string {
	if len(sha) >= 40 {
		return sha[:7]
	}
	return sha
}

package release

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/config"
	"github.com/integrio-intropy/intropy-cli/internal/git"
	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/source"
)

// now is the clock, replaced in tests so a manifest is reproducible.
var now = time.Now

// Create publishes an immutable release manifest and pushes an annotated git
// tag. It changes no environment: what was running before is still running,
// and because the version resolves the same commit it resolves the same
// digests.
//
// Re-running for a version that already exists is safe. The existing manifest
// is compared against what this run would publish; if they agree, the release
// is left alone and only a missing git tag is repaired. If they disagree the
// version is being reused for something else, and that is refused.
func Create(ctx context.Context, opts Options) error {
	opts.applyDefaults()

	if opts.Version == "" {
		return errors.New("a version is required")
	}
	if err := command.RequireBinaries("git"); err != nil {
		return err
	}

	cfg, err := config.Load()
	if err != nil {
		return err
	}
	resolved := cfg.Resolve(config.Flags{GitopsRepo: opts.GitopsRepo})
	repoURL, err := resolved.RequireGitopsRepo()
	if err != nil {
		return err
	}

	fmt.Fprintf(opts.Stderr, "refreshing %s\n", repoURL)
	repo, err := gitops.Open(ctx, gitops.Options{URL: repoURL, Runner: opts.Runner, CacheRoot: opts.CacheRoot})
	if err != nil {
		return err
	}
	defer repo.Close()

	coord, err := gitops.FindComponent(repo.Root, opts.Component, opts.Domain, opts.System)
	if err != nil {
		return err
	}
	comp, err := gitops.LoadComponentConfig(gitops.JoinRel(repo.Root, coord.RelPath()))
	if err != nil {
		return err
	}
	if len(comp.Images) == 0 {
		return fmt.Errorf("%s declares no images, so there is nothing to release", coord)
	}

	g := git.Client{Runner: opts.Runner, Dir: opts.SourceDir}

	src, err := source.Inspect(ctx, g, comp.SourcePaths, opts.AllowDirty)
	if err != nil {
		return err
	}
	if len(src.Dirty) > 0 {
		fmt.Fprintf(opts.Stderr, "warning: releasing with %d uncommitted change(s) under the component's source paths\n", len(src.Dirty))
	}

	// Ref defaults to HEAD, which Inspect has already checked. A different ref
	// is resolved here and checked for reachability the same way.
	commit := src.Commit
	if opts.Ref != "HEAD" {
		commit, err = g.RevParse(ctx, opts.Ref)
		if err != nil {
			return fmt.Errorf("resolve ref %s: %w", opts.Ref, err)
		}
		pushed, err := g.IsAncestor(ctx, commit, gitops.RemoteName+"/"+src.Branch)
		if err != nil {
			return err
		}
		if !pushed {
			return &source.UnpushedCommitError{Commit: commit, Branch: gitops.RemoteName + "/" + src.Branch}
		}
	}

	reg, err := NewRegistry(opts.UserAgent)
	if err != nil {
		return err
	}

	releasesRepo := ReleasesRepo(comp.Images[0].Name)
	ref := Ref(releasesRepo, opts.Version)

	// Look before publishing. A retry after a partial run has to recognise its
	// own earlier work, and that is only possible while the existing manifest
	// is still there to compare against.
	existing, err := lookup(ctx, reg, ref)
	if err != nil {
		return err
	}

	// Registry's Resolve matches source.Resolver, so no adapter is needed.
	var pins []source.Pin
	if opts.Watch {
		pins, err = source.WatchResolveDigests(ctx, reg, comp, commit, source.WatchOptions{Stderr: opts.Stderr})
	} else {
		pins, err = source.ResolveDigests(ctx, reg, comp, commit)
	}
	if err != nil {
		return err
	}

	basis, from, err := resolveBasis(ctx, reg, g, releasesRepo, commit, opts.Since, opts.Version)
	if err != nil {
		return err
	}

	var changes []Change
	if from != "" {
		if changes, err = Changelog(ctx, g, from, commit, comp.SourcePaths); err != nil {
			return err
		}
	}

	m := &Manifest{
		SchemaVersion: SchemaVersion,
		Component:     coord.Component,
		Version:       opts.Version,
		CreatedAt:     now().UTC().Truncate(time.Second),
		CreatedBy:     committer(),
		Source:        Source{Commit: commit, Ref: opts.Ref, Repo: repoURL},
		Images:        images(pins),
		Changes:       changes,
		ChangeBasis:   basis,
	}
	m.Notes = RenderNotes(changes, basis)

	result := Result{
		Component: m.Component,
		Version:   m.Version,
		Ref:       ref,
		Tag:       TagName(coord.Component, opts.Version),
		Manifest:  m,
	}

	switch {
	case existing == nil:
		digest, err := Push(ctx, reg, ref, m)
		if err != nil {
			return err
		}
		result.Digest, result.Created = digest, true
		fmt.Fprintf(opts.Stderr, "published %s\n", ref)

	case existing.SameRelease(m):
		// Already published, identically. Report the release that exists
		// rather than the one this run would have built.
		desc, err := reg.Resolve(ctx, ref)
		if err != nil {
			return err
		}
		result.Digest, result.Manifest = desc.Digest, existing
		fmt.Fprintf(opts.Stderr, "%s already published; nothing to do\n", ref)

	default:
		return fmt.Errorf("%s already exists and describes a different release (%s vs %s)\n"+
			"a release is immutable: pick a new version, or delete the tag in the registry if it was published in error",
			ref, shortSHA(existing.Source.Commit), shortSHA(m.Source.Commit))
	}

	// Tag after publishing. The manifest is what a release is; the tag is a
	// convenience for people reading git log, and nothing in this CLI reads it
	// — release discovery goes through the registry. So a tag that cannot be
	// pushed is reported and does not fail the command, and re-running repairs
	// it against the manifest that already exists.
	result.Tagged = tag(ctx, g, result.Tag, commit, m, opts.Stderr)

	return report(opts, result)
}

// lookup reads the manifest already published at ref, if any.
func lookup(ctx context.Context, reg Registry, ref string) (*Manifest, error) {
	m, err := Pull(ctx, reg, ref)
	switch {
	case err == nil:
		return m, nil
	case errors.Is(err, ErrNotFound):
		return nil, nil
	case errors.Is(err, ErrNotRelease):
		// Something else holds this tag. Publishing over it would destroy
		// whatever it is.
		return nil, fmt.Errorf("%s already exists and is not a release manifest: %w", ref, err)
	default:
		return nil, err
	}
}

// resolveBasis decides what the changelog is measured against, and returns the
// commit to start from. An empty from means there is nothing to measure.
func resolveBasis(ctx context.Context, reg Registry, g git.Client, releasesRepo, commit, since, version string) (ChangeBasis, string, error) {
	if since != "" {
		from, err := g.RevParse(ctx, since)
		if err != nil {
			return ChangeBasis{}, "", fmt.Errorf("resolve since %s: %w", since, err)
		}
		ancestor, err := g.IsAncestor(ctx, from, commit)
		if err != nil {
			return ChangeBasis{}, "", err
		}
		if !ancestor {
			return ChangeBasis{}, "", fmt.Errorf("since %s is not an ancestor of the commit being released (%s), so there is no range between them", since, shortSHA(commit))
		}
		return ChangeBasis{Kind: BasisExplicit, Ref: since}, from, nil
	}

	prev, err := PreviousRelease(ctx, reg, g, releasesRepo, commit, version)
	if err != nil {
		return ChangeBasis{}, "", err
	}
	if prev == nil {
		return ChangeBasis{Kind: BasisInitial}, "", nil
	}
	return ChangeBasis{
		Kind:    BasisRelease,
		Version: prev.Version,
		Commit:  prev.Source.Commit,
	}, prev.Source.Commit, nil
}

// TagName is the annotated tag for a release. Component-prefixed because these
// are monorepos: a bare v1.4.2 would collide the moment a second component in
// the same repository cut a release.
func TagName(component, version string) string {
	return component + "/v" + version
}

// tag creates and pushes the annotated tag, reporting whether it reached the
// remote. Every failure is a warning: the release is already published, and
// the tag is not load-bearing.
func tag(ctx context.Context, g git.Client, name, commit string, m *Manifest, stderr io.Writer) bool {
	at, exists, err := g.TagCommit(ctx, name)
	if err != nil {
		fmt.Fprintf(stderr, "warning: could not read tag %s: %v\n", name, err)
		return false
	}

	switch {
	case exists && at != commit:
		fmt.Fprintf(stderr, "warning: tag %s already points at %s, not %s; leaving it alone\n", name, shortSHA(at), shortSHA(commit))
		return false
	case !exists:
		if err := g.Tag(ctx, name, tagMessage(m), commit); err != nil {
			fmt.Fprintf(stderr, "warning: could not create tag %s: %v\n", name, err)
			return false
		}
	}

	// Pushing a tag the remote already has is a no-op, which is what makes
	// this safe to repeat.
	if err := g.Push(ctx, gitops.RemoteName, "refs/tags/"+name); err != nil {
		fmt.Fprintf(stderr, "warning: release %s is published, but its git tag could not be pushed: %v\n", m.Version, err)
		fmt.Fprintf(stderr, "         the release is valid without it; re-run to repair the tag\n")
		return false
	}
	fmt.Fprintf(stderr, "tagged %s\n", name)
	return true
}

func tagMessage(m *Manifest) string {
	return fmt.Sprintf("%s %s\n\n%s", m.Component, m.Version, m.Notes)
}

func images(pins []source.Pin) []Image {
	out := make([]Image, 0, len(pins))
	for _, p := range pins {
		out = append(out, Image{Name: p.Image, Digest: p.Digest})
	}
	return out
}

func committer() string {
	for _, key := range []string{"GITLAB_USER_EMAIL", "GITHUB_ACTOR", "USER"} {
		if v := os.Getenv(key); v != "" {
			return v
		}
	}
	return ""
}

func report(opts Options, r Result) error {
	if opts.OutputFormat == OutputJSON {
		enc := json.NewEncoder(opts.Stdout)
		enc.SetIndent("", "  ")
		return enc.Encode(r)
	}
	return renderCreated(opts.Stdout, r)
}
package release

import (
	"io"
	"os"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/git"
)

const (
	OutputPlain = "plain"
	OutputJSON  = "json"
)

// Options configures Create and View.
type Options struct {
	// Component is the component name; Domain and System disambiguate it when
	// the name occurs more than once.
	Component string
	Domain    string
	System    string

	// Version is the release version. Required by Create; View takes it as a
	// positional argument instead.
	Version string

	// Ref is the source revision to release. Defaults to HEAD.
	// Internal test seam — not exposed as a CLI flag.
	Ref string

	// Since names the starting point for the changelog when there is no
	// previous release to measure from. Internal test seam — not exposed as a
	// CLI flag.
	Since string

	// GitopsRepo overrides the configured GitOps repository URL.
	GitopsRepo string

	// SourceDir is the source repository to read from; defaults to the working
	// directory.
	SourceDir string

	// AllowDirty permits uncommitted changes under the component's sourcePaths.
	AllowDirty bool

	// Watch polls the registry until the commit's images appear, instead of
	// failing immediately when CI has not published them yet.
	Watch bool

	// OutputFormat is "plain" or "json".
	OutputFormat string

	// Limit caps how many releases List reports, newest first. Zero means all.
	// Internal — not exposed as a CLI flag.
	Limit int

	// CacheRoot overrides where GitOps checkouts are cached.
	CacheRoot string

	Runner    command.Runner
	UserAgent string
	Stdout    io.Writer
	Stderr    io.Writer
}

func (o *Options) applyDefaults() {
	if o.Runner == nil {
		o.Runner = git.DefaultRunner()
	}
	if o.SourceDir == "" {
		o.SourceDir = "."
	}
	if o.Ref == "" {
		o.Ref = "HEAD"
	}
	if o.OutputFormat == "" {
		o.OutputFormat = OutputPlain
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
}

// Result is the machine-readable outcome of Create.
//
// Field names are stable and additive-only.
type Result struct {
	Component string `json:"component"`
	Version   string `json:"version"`
	Ref       string `json:"ref"`
	Digest    string `json:"digest"`

	// Created is false when the release already existed and this run
	// recognised its own earlier work rather than publishing again.
	Created bool `json:"created"`

	// Tag is the annotated git tag, and Tagged reports whether it reached the
	// remote. A release is valid without its tag; the tag is for people
	// reading git log.
	Tag    string `json:"tag"`
	Tagged bool   `json:"tagged"`

	Manifest *Manifest `json:"manifest"`
}
package release

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/git"
)

// InitialNotes is what a release with no basis for comparison says, rather
// than leaving the notes blank and letting a reader guess.
const InitialNotes = "Initial release."

// Ancestry answers whether one commit descends from another. It is the seam
// that lets predecessor selection be tested without a real repository, and is
// satisfied by git.Client.
type Ancestry interface {
	IsAncestor(ctx context.Context, ancestor, descendant string) (bool, error)
}

// PreviousRelease finds the release that commit most recently descends from.
//
// The registry is the authority for which releases exist — a git tag that
// failed to push must not hide one — but "which release does this commit
// descend from" is a lineage question, so ancestry decides between the
// candidates rather than a version sort. Sorting by version breaks the moment
// history branches: a hotfix cut from a maintenance branch would take the
// newer release on the mainline as its predecessor and report a changelog full
// of commits it does not contain.
//
// Releases the commit does not descend from are skipped. Of those it does, the
// nearest wins — the one every other candidate is an ancestor of.
//
// The version being released is excluded from the candidates. Re-running
// create for a version that already exists must reproduce the manifest it
// published the first time, and a release whose own commit is an ancestor of
// itself — git counts equal commits as ancestors — would otherwise become its
// own predecessor and change the basis on every retry.
//
// A nil manifest with a nil error means there is no predecessor: either
// nothing has been released, or nothing released is an ancestor.
func PreviousRelease(ctx context.Context, reg Registry, anc Ancestry, releasesRepo, commit, excludeVersion string) (*Manifest, error) {
	versions, err := ListVersions(ctx, reg, releasesRepo)
	if err != nil {
		// Never released: the repository does not exist yet.
		if errors.Is(err, ErrNotFound) {
			return nil, nil
		}
		return nil, fmt.Errorf("list releases in %s: %w", releasesRepo, err)
	}

	var candidates []*Manifest
	for _, v := range versions {
		if v == excludeVersion {
			continue
		}
		m, err := Pull(ctx, reg, Ref(releasesRepo, v))
		if err != nil {
			// One unreadable tag must not make every later release
			// unchangeloggable. Skip it; the basis simply reaches further back.
			if errors.Is(err, ErrNotRelease) || errors.Is(err, ErrNotFound) {
				continue
			}
			return nil, fmt.Errorf("read release %s: %w", v, err)
		}

		descends, err := anc.IsAncestor(ctx, m.Source.Commit, commit)
		if err != nil {
			// A release built from a commit this clone has never seen is not
			// an ancestor as far as we can tell, and not a reason to fail.
			continue
		}
		if descends {
			candidates = append(candidates, m)
		}
	}

	return nearest(ctx, anc, candidates)
}

// nearest returns the candidate that every other candidate is an ancestor of.
func nearest(ctx context.Context, anc Ancestry, candidates []*Manifest) (*Manifest, error) {
	if len(candidates) == 0 {
		return nil, nil
	}

	best := candidates[0]
	for _, c := range candidates[1:] {
		// c is nearer when best is an ancestor of it.
		nearer, err := anc.IsAncestor(ctx, best.Source.Commit, c.Source.Commit)
		if err != nil {
			return nil, err
		}
		if nearer {
			best = c
		}
	}
	return best, nil
}

// Changelog lists the commits in from..to that touched sourcePaths.
//
// from is exclusive and to is inclusive, matching git's range syntax: the
// predecessor's own commit is already released, so it is not part of what
// changed.
func Changelog(ctx context.Context, g git.Client, from, to string, sourcePaths []string) ([]Change, error) {
	commits, err := g.Log(ctx, from+".."+to, sourcePaths...)
	if err != nil {
		return nil, err
	}

	changes := make([]Change, 0, len(commits))
	for _, c := range commits {
		changes = append(changes, Change{Commit: c.SHA, Subject: c.Subject})
	}
	return changes, nil
}

// RenderNotes turns the changelog into the manifest's notes.
func RenderNotes(changes []Change, basis ChangeBasis) string {
	if basis.Kind == BasisInitial && len(changes) == 0 {
		return InitialNotes
	}
	if len(changes) == 0 {
		return ""
	}

	var b strings.Builder
	for _, c := range changes {
		fmt.Fprintf(&b, "- %s\n", c.Subject)
	}
	return b.String()
}
